        {
            Exp, Exp2, Exp10, Log, Log2, Log10, Pow,
            Sin, Cos, SinCos, Tan, Asin, Acos, Atan, Atan2,
            Sinh, Cosh, Tanh, Acosh,
            ExpOverflow, ExpUnderflow, ExpPosInf, ExpNegInf, ExpNaN,
            LogEdges, TrigEdges, AtanEdges, PowEdges,
        }

        public T Type;

        // Type-scaled closeness: absorbs the few-ULP gap between DetMath and libm, and the absolute
        // form (1 + |expected|) keeps zero-crossings (sin/cos/atan) from inflating relative error.
        static void Close(float got, float expected)
        {
            
            const float tol = 1e-5f;
            
            
            float diff = math.abs(got - expected);
            float scale = (float)1 + math.abs(expected);
            Assert.IsTrue(diff <= tol * scale);
        }

        public void Execute()
        {
            switch (Type)
            {
                case T.Exp:   Sweep(T.Exp,   (float)(-20), (float)20);  break;
                case T.Exp2:  Sweep(T.Exp2,  (float)(-20), (float)20);  break;
                case T.Exp10: Sweep(T.Exp10, (float)(-8),  (float)8);   break;
                case T.Log:   Sweep(T.Log,   (float)0.05,  (float)100); break;
                case T.Log2:  Sweep(T.Log2,  (float)0.05,  (float)100); break;
                case T.Log10: Sweep(T.Log10, (float)0.05,  (float)100); break;
                case T.Sin:   Sweep(T.Sin,   (float)(-10), (float)10);  break;
                case T.Cos:   Sweep(T.Cos,   (float)(-10), (float)10);  break;
                case T.SinCos:Sweep(T.SinCos,(float)(-10), (float)10);  break;
                case T.Tan:   Sweep(T.Tan,   (float)(-1.3), (float)1.3);break;   // stay off the poles
                case T.Asin:  Sweep(T.Asin,  (float)(-0.99),(float)0.99);break;
                case T.Acos:  Sweep(T.Acos,  (float)(-0.99),(float)0.99);break;
                case T.Atan:  Sweep(T.Atan,  (float)(-100),(float)100); break;
                case T.Sinh:  Sweep(T.Sinh,  (float)(-10), (float)10);  break;
                case T.Cosh:  Sweep(T.Cosh,  (float)(-10), (float)10);  break;
                case T.Tanh:  Sweep(T.Tanh,  (float)(-10), (float)10);  break;
                case T.Acosh: Sweep(T.Acosh, (float)1,     (float)20);  break;
                case T.Pow:   PowSweep();  break;
                case T.Atan2: Atan2Sweep(); break;
                case T.ExpOverflow:  Assert.IsTrue(DetMath.Exp((float)10000) == (float)float.PositiveInfinity); break;
                case T.ExpUnderflow: Assert.IsTrue(DetMath.Exp((float)(-10000)) == (float)0); break;
                case T.ExpPosInf:    Assert.IsTrue(DetMath.Exp((float)float.PositiveInfinity) == (float)float.PositiveInfinity); break;
                case T.ExpNegInf:    Assert.IsTrue(DetMath.Exp((float)float.NegativeInfinity) == (float)0); break;
                case T.ExpNaN:       { float en = DetMath.Exp((float)float.NaN); Assert.IsTrue(en != en); } break;
                case T.LogEdges:  LogEdges();  break;
                case T.TrigEdges: TrigEdges(); break;
                case T.AtanEdges: AtanEdges(); break;
                case T.PowEdges:  PowEdges();  break;
            }
        }

        void Sweep(T k, float lo, float hi)
        {
            const int N = 500;
            for (int i = 0; i <= N; i++)
            {
                float x = lo + (hi - lo) * ((float)i / (float)N);
                switch (k)
                {
                    case T.Exp:   Close(DetMath.Exp(x),   math.exp(x));   break;
                    case T.Exp2:  Close(DetMath.Exp2(x),  math.exp2(x));  break;
                    case T.Exp10: Close(DetMath.Exp10(x), math.exp10(x)); break;
                    case T.Log:   Close(DetMath.Log(x),   math.log(x));   break;
                    case T.Log2:  Close(DetMath.Log2(x),  math.log2(x));  break;
                    case T.Log10: Close(DetMath.Log10(x), math.log10(x)); break;
                    case T.Sin:   Close(DetMath.Sin(x),   math.sin(x));   break;
                    case T.Cos:   Close(DetMath.Cos(x),   math.cos(x));   break;
                    case T.SinCos:
                        DetMath.SinCos(x, out float s, out float c);
                        Close(s, math.sin(x)); Close(c, math.cos(x));
                        break;
                    case T.Tan:   Close(DetMath.Tan(x),   math.tan(x));   break;
                    case T.Asin:  Close(DetMath.Asin(x),  math.asin(x));  break;
                    case T.Acos:  Close(DetMath.Acos(x),  math.acos(x));  break;
                    case T.Atan:  Close(DetMath.Atan(x),  math.atan(x));  break;
                    case T.Sinh:  Close(DetMath.Sinh(x),  math.sinh(x));  break;
                    case T.Cosh:  Close(DetMath.Cosh(x),  math.cosh(x));  break;
                    case T.Tanh:  Close(DetMath.Tanh(x),  math.tanh(x));  break;
                    case T.Acosh: Close(DetMath.Acosh(x), math.log(x + math.sqrt(x * x - (float)1))); break;
                }
            }
        }

        void PowSweep()
        {
            const int N = 60;
            for (int i = 0; i <= N; i++)
            {
                float x = (float)0.1 + (float)9.9 * ((float)i / (float)N);
                for (int j = 0; j <= N; j++)
                {
                    float y = (float)(-3) + (float)6 * ((float)j / (float)N);
                    Close(DetMath.Pow(x, y), math.pow(x, y));
                }
            }
        }

        void Atan2Sweep()
        {
            const int N = 40;
            for (int i = 0; i <= N; i++)
            {
                float y = (float)(-5) + (float)10 * ((float)i / (float)N);
                for (int j = 0; j <= N; j++)
                {
                    float x = (float)(-5) + (float)10 * ((float)j / (float)N);
                    if (math.abs(x) < (float)0.05 && math.abs(y) < (float)0.05) continue;   // skip origin
                    Close(DetMath.Atan2(y, x), math.atan2(y, x));
                }
            }
        }

        void LogEdges()
        {
            float inf = (float)float.PositiveInfinity;
            float ninf = (float)float.NegativeInfinity;
            float nan = (float)float.NaN;
            Assert.IsTrue(DetMath.Log((float)0) == ninf);
            float ln = DetMath.Log((float)(-1)); Assert.IsTrue(ln != ln);
            Assert.IsTrue(DetMath.Log(inf) == inf);
            Assert.IsTrue(math.abs(DetMath.Log((float)1)) <= (float)1e-6);
            float lnan = DetMath.Log(nan); Assert.IsTrue(lnan != lnan);
        }

        void TrigEdges()
        {
            float inf = (float)float.PositiveInfinity;
            float nan = (float)float.NaN;
            float si = DetMath.Sin(inf); Assert.IsTrue(si != si);
            float ci = DetMath.Cos(inf); Assert.IsTrue(ci != ci);
            float sn = DetMath.Sin(nan); Assert.IsTrue(sn != sn);
        }

        void AtanEdges()
        {
            float inf = (float)float.PositiveInfinity;
            float ninf = (float)float.NegativeInfinity;
            Assert.IsTrue(math.abs(DetMath.Atan(inf) - (float)1.5707963267948966) <= (float)1e-5);
            Assert.IsTrue(math.abs(DetMath.Atan(ninf) + (float)1.5707963267948966) <= (float)1e-5);
        }

        void PowEdges()
        {
            Assert.IsTrue(DetMath.Pow((float)0, (float)2) == (float)0);
        }
    }

